CREATE TABLE P360_PRODUCTS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, VERSION NUMBER(19), NAME VARCHAR2(80) NOT NULL, CATEGORY VARCHAR2(80) NOT NULL, PRICE NUMBER(12,2) NOT NULL, STORE_ID NUMBER(19) NOT NULL, STOCK INTEGER NOT NULL CHECK(STOCK >= 0), ACTIVE BOOLEAN NOT NULL);
CREATE INDEX IDX_PRODUCT_STORE ON P360_PRODUCTS(STORE_ID);
CREATE TABLE P360_RESERVATIONS (ID VARCHAR2(80) PRIMARY KEY, DIGEST VARCHAR2(64) NOT NULL, PAYLOAD CLOB NOT NULL, RELEASED BOOLEAN NOT NULL);
